// BuildDiff compares two checkpoint files inside evidenceDir tensor by tensor.
func BuildDiff(evidenceDir, file1, file2 string) (interface{}, error) {
        pathA := filepath.Join(evidenceDir, file1)
        pathB := filepath.Join(evidenceDir, file2)

        cfA, err := checkpoint.Parse(pathA)
        if err != nil {
