        }
        if cfB == nil {
                return nil, fmt.Errorf("diff: %s: not found", file2)
        }

        tensorsA := make(map[string]types.TensorInfo, len(cfA.Tensors))
        for _, t := range cfA.Tensors {
                tensorsA[t.Name] = t
        }
        tensorsB := make(map[string]types.TensorInfo, len(cfB.Tensors))
        for _, t := range cfB.Tensors {
                tensorsB[t.Name] = t
        }

        names := map[string]struct{}{}
        for name := range tensorsA {
                names[name] = struct{}{}
        }
        for name := range tensorsB {
                names[name] = struct{}{}
        }
        sortedNames := make([]string, 0, len(names))
        for name := range names {
                sortedNames = append(sortedNames, name)
        }
        sort.Strings(sortedNames)

        onlyInA := []string{}
        onlyInB := []string{}
        common := 0
        shapeMismatches := 0
        tensorDiffs := make([]diffTensorResult, 0, len(sortedNames))

        for _, name := range sortedNames {
                ta, okA := tensorsA[name]
                tb, okB := tensorsB[name]

                var shapeA []uint32
                var shapeB []uint32
                if okA {
                        shapeA = ta.Shape
                }
                if okB {
                        shapeB = tb.Shape
                }

                shapeMatch := okA && okB && shapesEqual(ta.Shape, tb.Shape)
                result := diffTensorResult{
                        Name:       name,
                        ShapeMatch: shapeMatch,
                        ShapeA:     shapeA,
                        ShapeB:     shapeB,
                }

                if okA && okB {
                        common++
                        if !shapeMatch {
                                shapeMismatches++
                        } else {
                                maxDiff, meanDiff, err := float32DiffStats(ta, tb)
                                if err != nil {
                                        return nil, fmt.Errorf("diff: tensor %s: %w", name, err)
                                }
                                result.MaxAbsDiff = &maxDiff
                                result.MeanAbsDiff = &meanDiff
                        }
                } else if okA {
                        onlyInA = append(onlyInA, name)
                } else {
                        onlyInB = append(onlyInB, name)
                }

                tensorDiffs = append(tensorDiffs, result)
        }

        return diffOutput{
