func float32DiffStats(a, b types.TensorInfo) (float64, float64, error) {
        if a.Dtype != float32Dtype || b.Dtype != float32Dtype {
                return 0, 0, fmt.Errorf("unsupported dtype %d/%d; only float32 tensors are supported", a.Dtype, b.Dtype)
        }
        if len(a.Data) != len(b.Data) {
                return 0, 0, fmt.Errorf("data length mismatch %d/%d", len(a.Data), len(b.Data))
        }
        if len(a.Data)%4 != 0 {
                return 0, 0, fmt.Errorf("non-float32 data length %d", len(a.Data))
        }

        n := len(a.Data) / 4
        if n == 0 {
                return 0, 0, nil
        }

        var maxDiff, sumDiff float64
        for i := 0; i < n; i++ {
                fa := math.Float32frombits(binary.LittleEndian.Uint32(a.Data[i*4 : i*4+4]))
                fb := math.Float32frombits(binary.LittleEndian.Uint32(b.Data[i*4 : i*4+4]))
                d := math.Abs(float64(fa - fb))
                if d > maxDiff {
                        maxDiff = d
                }
                sumDiff += d
        }
        return maxDiff, sumDiff / float64(n), nil
}
